01-javascript/53-reduce.solution:
function groupByStatus(results) {
  return results.reduce((groups, result) => {
    if (!groups[result.status]) {
      groups[result.status] = [];
    }

    groups[result.status].push(result.name);
    return groups;
  }, {});
}

